def isConnected(curr, dest, adj, visited,conect):
    if adj == {}:
        return
    if curr == dest:
        conect[0] = True
        return
    if curr in visited:
        return
    visited[curr] = True
    for node in adj[curr]:
        isConnected(node, dest, adj, visited,conect)

