class Unionfind(object):
    def __init__(self, size):
        self.root = [i for i in range(size)]
        self.node_num = size
        self.count = size 
    def find(self, x):
        return self.root[x]
    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            for i in range(self.node_num):
                if self.root[i] == root_y:
                    self.root[i] = root_x 
            self.count -= 1
            return False
        else:
            return True
    def connect(self, x, y):
        return self.find(x) == self.find(y)

