# try 2: union find with quick union and rank optimization
class Unionfind(object):
    def __init__(self, size):
        self.parent = [i for i in range(size)]
        self.rank = [1] * size
        self.count = size
    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x
    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.rank[root_x] > self.rank[root_y]:
                self.parent[root_y] = root_x  
            elif self.rank[root_x] < self.rank[root_y]:
                self.parent[root_x] = root_y
            else:
                self.rank[root_x] += 1
                self.parent[root_y] = root_x  
            self.count -= 1
            return False
        else:
            return True
    def connect(self, x, y):
        return self.find(x) == self.find(y)

class Solution(object):
    def findRedundantConnection(self, edges):
        """
        :type edges: List[List[int]]
        :rtype: List[int]
        """
        n = len(edges)
        uf = Unionfind(n)
        output = None
        for edge in edges:
            index_i = edge[0] - 1
            index_j = edge[1] - 1
            redundant_edge = uf.union(index_i, index_j)
            if redundant_edge:
