class Solution(object):
    def findRedundantConnection(self, edges):
        """
        :type edges: List[List[int]]
        :rtype: List[int]
        """

        par = [i for i in range(len(edges)+ 1)]
        rank = [1 for _ in range(len(edges) + 1)]

        def find_parent(node):
            p = par[node]
            while not p == par[p]:
                # par[p] = par[par[p]]
                p = par[p]

            return p

        def union(u, v):
            par_u = find_parent(u)
            par_v = find_parent(v)

            # If they are already the same
            if par_u == par_v:
                return False

            # If they are different union
            if rank[par_u] > rank[par_v]:
                rank[par_u] += rank[par_v]
                par[par_v] = par_u
            else:
                rank[par_v] += rank[par_u]
                par[par_u] = par_v
            return True

        for u, v in edges:
            if not union(u, v):
                return [u, v]

