class Solution(object):

    def find(self, p):
        return self.quick_find_links[p-1]

    def union_is_redundant(self, p, q):
        p_id = self.find(p)
        q_id = self.find(q)

        if (p_id == q_id):
            return True

        self.quick_find_links = [ link if link != p_id else q_id for link in self.quick_find_links ]
        return False

    def findRedundantConnection(self, edges):
        """
        :type edges: List[List[int]]
        :rtype: List[int]
        """
        # N edges and N nodes. Otherwise build out list as you go
        # index = node # - 1, could use a map but they are the ones who decided to index starting at 1
        self.quick_find_links = [ i + 1 for i in range(len(edges))]

        redundant_edges = []
        for edge in edges:
            if (self.union_is_redundant(edge[0], edge[1])):
                redundant_edges.append(edge)

        return redundant_edges[-1] if redundant_edges else None

