    def findRedundantConnection(self, edges):
        """
        :type edges: List[List[int]]
        :rtype: List[int]
        """
        parent = [i for i in range(1, len(edges) + 1)]

        def find(node):
            if parent[node - 1] == node:
                return node
            else:
                return find(parent[node - 1])

        def union(u, v):
            uroot = find(u)
            vroot = find(v)

            if uroot != vroot:
                parent[vroot - 1] = uroot

        for edge in edges:
            if find(edge[0]) == find(edge[1]):
                return edge
            else:
                union(edge[0], edge[1])

