    def lengthOfLIS(self, nums: List[int]) -> int:
        res = 1
        seq = sorted(list(set(nums)))
        smap = {k:v for v, k in enumerate(seq)}
        imap = {}

        for i, x in enumerate(nums):
            prevs = set(seq[:smap[x]]).intersection(set(nums[:i]))
            if prevs: 
                imap[x] = max(imap.get(p, 0) for p in prevs) + 1
            else:
                imap[x] = 1
            res = max(res, imap[x])

        return res

