class Solution:
    def lengthOfLIS(self, nums: List[int]) -> int:
        n = len(nums)
        memo = []
        index = -1
        current_max = 0
        while index >= -n:
            val = 1 + self.find(memo, nums[index])
            current_max = max(current_max, val)
            memo.append((val, nums[index]))
            index -= 1
        return current_max

    def find(self, memo: List, num: int) -> int:
        memo.sort(reverse=True)
        for (x, y) in memo:
            if num < y:
                return x
        return 0

