class Solution:
    def _helper(self, k, bound, lst, nums):
        max_val = 0
        for j in range(k, len(lst)):
            if bound < nums[j]:
                if lst[j] >= max_val:
                    max_val = lst[j]
        return max_val


    def lengthOfLIS(self, nums: List[int]) -> int:
        if len(nums) <= 1:
            return 1
        lst = [0] * len(nums)
        lst[-1] = 1
        for i in range(len(nums)-2, -1, -1):
            lst[i] = 1 + self._helper(i+1, nums[i], lst, nums)
        return max(lst)

