        T, LIS = [1 for _ in range(len(nums))], 1
        for i in range(1, len(nums)):
            m = 1
            for j in range(i - 1, -1, -1):
                if nums[j] < nums[i]:
                    if 1 + T[j] > m:
                        m = 1 + T[j]
            T[i] = m
            if m > LIS:
                LIS = m
        print(T)
        return LIS

