    def lengthOfLIS1(self, nums: List[int]) -> int:

        cache = dict()

        def recur(i, bef):
            if (i, bef) in cache:
                return cache[(i,bef)]
            if i == len(nums):
                return 0

            longest = 0

            for c in range(i, len(nums)):
                if nums[c] > bef:
                    cur = 1 + recur(c + 1, nums[c])
                    longest = max(longest, cur)

            cache[(i,bef)] = longest

            return cache[(i,bef)]



        return recur(0, float("-inf"))

