class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        n = len(isConnected)
        adj = defaultdict(list)

        for r in range(n):
            for c in range(n):
                if isConnected[r][c] == 1:
                    adj[r].append(c)
                    adj[c].append(r)

        visited = set()
        def dfs(node):
            if node in visited:
                return

            visited.add(node)
            for next_node in adj[node]:
                dfs(next_node)

        res = 0
        for node in range(n):
            if node not in visited:
                res += 1
                dfs(node)

        return res

