class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        num_provinces, num_cities = 0, len(isConnected)
        all_cities = set(range(num_cities))
        while all_cities:
            queue = deque([all_cities.pop()])
            visited = set([queue[0]])
            num_provinces += 1
            while queue:
                city = queue.popleft()
                for city, conn in enumerate(isConnected[city]):
                    if conn and city not in visited:
                        visited.add(city)
                        all_cities.remove(city)
                        queue.append(city)

        return num_provinces

