    def BFS(self,node,isConnected,visited):
        queue=collections.deque()
        queue.append(node)
        while len(queue):
            nei=queue.popleft()
            visited[nei]=True
            for i in range(0,len(isConnected)):
                if(isConnected[nei][i]==1 and not visited[i]):
                    queue.append(i)

    def findCircleNum(self, isConnected: List[List[int]]) -> int:
