class UnionFind:
    def __init__(self, n):
        self.group = [i for i in range(n)]

    def _find(self, x):
        if self.group[x] != x:
            self.group[x] = self._find(self.group[x])
        return self.group[x]

    def _union(self, x, y):
        x_group = self._find(x)
        y_group = self._find(y)

        if x_group == y_group:
            return False

        n = len(self.group)
        if x_group <= y_group:
            for i in range(n):
                if self.group[i] == y_group:
                    self.group[i] = x_group
        else:
            for i in range(n):
                if self.group[i] == x_group:
                    self.group[i] = y_group
        return True



