class Solution:
    def fib(self, n: int) -> int:

        memo = []

        def fib_helper(n):
            if n == 0:
                return 0
            if n == 1:
                return 1

            n_minus_one = memo[n - 1] if (n - 1) in memo else fib_helper(n - 1)
            n_minus_two = memo[n - 2] if (n - 2) in memo else fib_helper(n - 2)

            return n_minus_one + n_minus_two

        return fib_helper(n)

