class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        # lower bound and upper bound
        # bs

        # if cannot found it will be n or 0
        # find the first index >= x
        # find the first index >= x + 1

        # and then check whether it is the target

        if len(nums) == 0:
            return [-1, -1]

        l = 0
        r = len(nums)

        while l < r:
            m = l + (r - l) // 2

            if nums[m] >= target:
                r = m
            else:
                l = m + 1
        lb = l
        if l == len(nums):
            lb = -1
        else:
            if nums[l] != target:
                lb = -1 

        l = 0
        r = len(nums)

        while l < r:
            m = l + (r - l) // 2

            if nums[m] >= target+1:
                r = m
            else:
                l = m + 1
        ub = l
        if ub == 0:
            if nums[l] != target:
                ub = -1 
        else:
            ub = ub - 1
            if nums[ub] != target:
                ub = -1 

        return [lb, ub]

